        if 'r_fused' not in row: continue
        keys=['r_lf','r_labels_mlp','r_labels_linear','r_f_plus_labels_ridge','r_stacked','r_plain_mlp']
        complete=all(row[k] is not None for k in keys+['r_fused'])
        expected=complete and row['r_fused']>max(row[k] for k in keys)
        assert row['hidden_information_supported']==expected
        for k in keys:
            gain=row['gain_vs_'+k[2:]]
            if gain is not None: assert abs(gain-(row['r_fused']-row[k]))<1e-10
